from __future__ import annotations
from pathlib import Path
import base64, hashlib, zlib

ROOT = Path(__file__).resolve().parent
INV = ROOT / "dashboard" / "src" / "pages" / "inventory"
BASELINE = {'Tab3Stocktake.tsx': '73cfc927c8cb90b2f90e29a87cf82d154e58afe0', 'stocktake/types.ts': '0c326a0a62b64880505d408fa2f0b61d618e8a31', 'stocktake/parsers.ts': 'e5271ab413c2ccce48d92f552b763954ce3cbc15', 'stocktake/hooks/useStocktakeSessions.ts': '2a62981e6726fe546500a4c077183acee1dcc833', 'stocktake/StocktakeSessionCenter.tsx': '6bf1f6c33102325bc8e52a6086c3201ce7251c25'}
PAYLOADS = {'stocktake/hooks/useStocktakeCounting.ts': '', 'stocktake/hooks/useStocktakeReview.ts': '', 'stocktake/hooks/useStocktakeActions.ts': '', 'stocktake/StocktakeIdlePanel.tsx': '', 'stocktake/StocktakeIndependentWait.tsx': '', 'stocktake/StocktakeCountingPanel.tsx': '', 'stocktake/StocktakeReviewPanel.tsx': '', 'stocktake/StocktakeCountModals.tsx': '', 'stocktake/StocktakeDecisionModals.tsx': '', 'Tab3Stocktake.tsx': '', 'stocktake/hooks/useStocktakeState.ts': '', 'stocktake/hooks/useStocktakeLifecycle.ts': ''}

def fail(message: str) -> None:
    raise SystemExit(f"PATCH_ABORTED: {message}")

def normalize_bytes(path: Path) -> bytes:
    return path.read_bytes().replace(b"\r\n", b"\n")

def git_blob_sha(data: bytes) -> str:
    header = f"blob {len(data)}\0".encode("ascii")
    return hashlib.sha1(header + data).hexdigest()

def decode(name: str) -> str:
    return zlib.decompress(base64.b64decode(PAYLOADS[name])).decode("utf-8")

for relative, expected in BASELINE.items():
    path = INV / relative
    if not path.exists():
        fail(f"Baseline file missing: {relative}")
    actual = git_blob_sha(normalize_bytes(path))
    if actual != expected:
        fail(
            f"Baseline mismatch for {relative}: expected {expected}, got {actual}. "
            "No files changed."
        )

targets = {INV / relative: decode(relative) for relative in PAYLOADS}

for path, expected in targets.items():
    if path.name == "Tab3Stocktake.tsx":
        continue
    if path.exists():
        current = path.read_text(encoding="utf-8").replace("\r\n","\n")
        if current != expected:
            fail(
                "Refusing to overwrite existing different file: "
                f"{path.relative_to(ROOT)}. No files changed."
            )

tab = targets[INV / "Tab3Stocktake.tsx"]
combined = "\n".join(targets.values())
count_hook = targets[INV / "stocktake/hooks/useStocktakeCounting.ts"]

checks = {
    "TAB_ORCHESTRATOR_SIZE": len(tab.splitlines()) < 430,
    "TAB_NO_DIRECT_API": "authenticatedFetch(" not in tab,
    "TAB_NO_COUNT_PAYLOAD": "actual_quantity" not in tab,
    "TAB_NO_DECISION_PAYLOAD": (
        "count_attempt_id" not in tab
        and "authorizer_password" not in tab
    ),
    "STATE_HOOK": "export function useStocktakeState" in combined,
    "LIFECYCLE_HOOK": "export function useStocktakeLifecycle" in combined,
    "COUNTING_HOOK": "export function useStocktakeCounting" in combined,
    "REVIEW_HOOK": "export function useStocktakeReview" in combined,
    "ACTIONS_HOOK": "export function useStocktakeActions" in combined,
    "COUNT_STATUS_PRESERVED": "stock_status: row.stock_status" in combined,
    "APPROVE_ATTEMPT_PRESERVED": "count_attempt_id:" in combined,
    "RECOUNT_ATTEMPT_PRESERVED": combined.count("review.latest_attempt.id") >= 2,
    "COUNT_DRAFT_TENANT_SCOPE": (
        "wanasah_audit_draft:${companyScope}:${locationId}:${sid}" in combined
    ),
    "COUNT_DRAFT_CYCLE_SAFE": (
        'phase === "COUNTING"' in count_hook
        and "isAuditLocked" not in count_hook
    ),
    "BLIND_COUNT_PRESERVED": (
        "/count-sheet" in count_hook
        and "expected_quantity" not in count_hook
    ),
    "REVIEW_LOCATION_FAIL_CLOSED": "data.location_id !== locationId" in combined,
    "FULL_COUNT_START_PRESERVED": (
        '"/warehouse/unified/stocktake/start"' in combined
        and '"FULL_COUNT"' in combined
    ),
    "SESSION_CENTER_PRESERVED": "<StocktakeSessionCenter" in tab,
    "SERVER_STATUS_REFRESH_PRESERVED": "notifyStocktakeChanged" in combined,
    "NO_COMPANY_ID_PAYLOAD": "company_id" not in combined,
    "NO_EXPLICIT_ANY": (
        ": any" not in combined and "any[]" not in combined and "Promise<any>" not in combined
    ),
}
failed=[n for n,o in checks.items() if not o]
if failed:
    fail("In-memory verification failed: " + ", ".join(failed))

for path, content in targets.items():
    if path.name == "Tab3Stocktake.tsx":
        continue
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        print(f"UNCHANGED={path.relative_to(INV)}")
    else:
        path.write_text(content, encoding="utf-8")
        print(f"CREATED={path.relative_to(INV)}")

(INV/"Tab3Stocktake.tsx").write_text(tab, encoding="utf-8")
print("PATCHED=Tab3Stocktake.tsx")

written = (INV/"Tab3Stocktake.tsx").read_text(encoding="utf-8").replace("\r\n","\n")
post = {
    "TAB_IS_ORCHESTRATOR": (
        "useStocktakeState({" in written
        and "useStocktakeLifecycle({" in written
        and "useStocktakeCounting({" in written
        and "useStocktakeReview({" in written
        and "useStocktakeActions({" in written
    ),
    "TAB_NO_QUANTITY_INPUT": "QuantityInput" not in written,
    "TAB_NO_MODAL_IMPLEMENTATION": "<Modal" not in written,
    "TAB_NO_TOAST": "toast." not in written,
}
bad=[n for n,o in post.items() if not o]
if bad:
    fail("Post-write structural gate failed: " + ", ".join(bad))

print("STOCKTAKE_STATE_BOUNDARY=OK")
print("STOCKTAKE_LIFECYCLE_BOUNDARY=OK")
print("STOCKTAKE_COUNTING_HOOK_EXTRACTED=OK")
print("STOCKTAKE_REVIEW_HOOK_EXTRACTED=OK")
print("STOCKTAKE_ACTIONS_HOOK_EXTRACTED=OK")
print("STOCKTAKE_PRESENTATION_COMPONENTS_EXTRACTED=OK")
print("STOCKTAKE_CYCLE_DRAFT_PERSISTENCE_SAFE=OK")
print("STOCKTAKE_CONTRACTS_PRESERVED=OK")
print("STOCKTAKE_TAB_ORCHESTRATOR=OK")
print("MAIN_INVENTORY_STAGE4A2B_MODULARIZATION=OK")
